import math
from datetime import datetime
from pathlib import Path
import struct
import tempfile
from types import SimpleNamespace
import unittest
from zoneinfo import ZoneInfo

from tools.can_dashboard import model
from tools.logs import mlvlg, trc_to_mlg


def write_trace(path):
    generator = model.DemoGenerator()
    lines = [
        ";$FILEVERSION=1.1",
        ";$STARTTIME=46251.0734343518",
        "; Start time: 17.08.2026 01:45:44.728.0",
        "; Generated by test",
    ]
    number = 1
    offset_ms = 1000.0
    for tick in range(1, 9):
        elapsed = tick * model.BASE_TICK_SECONDS
        frames = (
            *generator.stock_context(tick, elapsed),
            *generator.group(tick, elapsed),
        )
        for frame in frames:
            payload = " ".join(f"{value:02X}" for value in frame.data)
            lines.append(
                f"{number:7d}) {offset_ms:12.4f} Rx   "
                f"{frame.arbitration_id:04X}  {len(frame.data)}  {payload}"
            )
            number += 1
            offset_ms += 0.1
        offset_ms = 1000.0 + tick * 10.24
    Path(path).write_text("\n".join(lines) + "\n", encoding="ascii")


def read_field_names(path):
    data = Path(path).read_bytes()
    header = struct.unpack(">6sHIIIHH", data[:mlvlg.MLG_HEADER_SIZE])
    field_count = header[-1]
    offset = mlvlg.MLG_HEADER_SIZE
    names = []
    for _ in range(field_count):
        descriptor = data[offset : offset + mlvlg.MLG_FIELD_SIZE]
        names.append(
            descriptor[1:35].split(b"\x00", 1)[0].decode("ascii")
        )
        offset += mlvlg.MLG_FIELD_SIZE
    return header, names


class TrcToMlgTest(unittest.TestCase):
    def test_conversion_preserves_snapshots_and_field_identity(self):
        with tempfile.TemporaryDirectory() as directory:
            source = Path(directory) / "capture.trc"
            output = Path(directory) / "capture.mlg"
            write_trace(source)
            summary = trc_to_mlg.convert_trace(source, output)
            validation = mlvlg.validate_mlg(output)
            header, names = read_field_names(output)

        self.assertEqual(summary.complete_snapshots, 8)
        self.assertEqual(summary.source_frames, 128)
        self.assertEqual(summary.telemetry_frames, 88)
        self.assertEqual(summary.mlg_records, 8)
        self.assertEqual(summary.bridge_records, 0)
        self.assertEqual(summary.mlg_fields, 87)
        self.assertEqual(validation.record_length, 348)
        self.assertEqual(validation.data_records, 8)
        self.assertEqual(header[0], b"MLVLG\x00")
        expected_start = math.floor(
            datetime(
                2026,
                8,
                17,
                1,
                45,
                44,
                728_000,
                tzinfo=ZoneInfo("Asia/Vladivostok"),
            ).timestamp()
            + 1.0015
        )
        self.assertEqual(header[2], expected_start)
        self.assertAlmostEqual(summary.first_snapshot_offset_ms, 1001.5)
        self.assertIn("Vehicle speed", names)
        self.assertIn("Knock timing state", names)
        self.assertIn("High-detonation surface selected", names)
        self.assertNotIn("gps_lat", names)
        self.assertNotIn("gps_lon", names)

    def test_force_cannot_overwrite_source_trace(self):
        with tempfile.TemporaryDirectory() as directory:
            source = Path(directory) / "capture.trc"
            write_trace(source)
            original = source.read_bytes()
            with self.assertRaisesRegex(
                trc_to_mlg.ConversionError,
                "overwrite the source trace",
            ):
                trc_to_mlg.convert_trace(source, source, force=True)
            self.assertEqual(source.read_bytes(), original)

    def test_nonfinite_start_time_is_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            source = Path(directory) / "capture.trc"
            output = Path(directory) / "capture.mlg"
            write_trace(source)
            content = source.read_text(encoding="ascii").replace(
                ";$STARTTIME=46251.0734343518",
                ";$STARTTIME=nan",
            )
            source.write_text(content, encoding="ascii")
            with self.assertRaisesRegex(
                trc_to_mlg.ConversionError,
                "invalid \\$STARTTIME",
            ):
                trc_to_mlg.convert_trace(source, output)
            self.assertFalse(output.exists())

    def test_ambiguous_and_nonexistent_local_start_times_are_rejected(self):
        local_times = (
            datetime(2026, 11, 1, 1, 30),
            datetime(2026, 3, 8, 2, 30),
        )
        for local_start in local_times:
            ole_days = (
                local_start - trc_to_mlg.OLE_AUTOMATION_EPOCH
            ).total_seconds() / 86_400
            trace = SimpleNamespace(
                path=Path("capture.trc"),
                start_time=str(ole_days),
            )
            with self.subTest(local_start=local_start), self.assertRaisesRegex(
                trc_to_mlg.ConversionError,
                "ambiguous or nonexistent",
            ):
                trc_to_mlg.trace_start_epoch(trace, "America/New_York")


if __name__ == "__main__":
    unittest.main()
